"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { ComicUploadForm } from '@/components/comic-upload-form';
import { ComicModal } from '@/components/comic-modal';
import { BookOpen, Plus, Trash2, Edit2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import type { Comic } from '@/lib/types';

export default function LongComicsPage() {
  const { comics, isAdmin, removeComic, parentCategories } = useAppStore();
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [selectedComic, setSelectedComic] = useState<Comic | null>(null);
  const [editingComic, setEditingComic] = useState<Comic | null>(null);

  const pageTitle = parentCategories['comics-long'] || '로그 백업';
  
  const longComics = comics.filter(c => c.type === 'long');

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('정말로 이 만화를 삭제하시겠습니까?')) {
      removeComic(id);
    }
  };

  return (
    <div className="min-h-screen bg-background">
      <Sidebar />
      
      <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0">
        <div className="max-w-6xl mx-auto px-6 py-12">
          {/* Header */}
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/20 flex items-center justify-center">
                <BookOpen className="w-5 h-5 text-primary" />
              </div>
              <div>
                <h1 className="text-2xl font-bold">{pageTitle}</h1>
                <p className="text-sm text-muted-foreground">Log Backup</p>
              </div>
            </div>
            
            {isAdmin && (
              <Button onClick={() => setShowUploadForm(!showUploadForm)}>
                <Plus className="w-4 h-4 mr-2" />
                새 만화
              </Button>
            )}
          </div>

          {/* Upload Form (Admin only) */}
          {isAdmin && (showUploadForm || editingComic) && (
            <div className="mb-8">
              <ComicUploadForm 
                type="long" 
                initialData={editingComic || undefined}
                onClose={() => {
                  setShowUploadForm(false);
                  setEditingComic(null);
                }} 
              />
            </div>
          )}

          {/* Comics Grid */}
          {longComics.length > 0 ? (
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 lg:grid-cols-6 gap-x-4 gap-y-8">
              {longComics.map((comic) => (
                <div
                  key={comic.id}
                  onClick={() => setSelectedComic(comic)}
                  className="group relative cursor-pointer flex flex-col"
                >
                  <div className="aspect-[3/4] rounded-md overflow-hidden bg-slate-100 border border-slate-200/60 shadow-sm relative">
                    <img
                      src={comic.thumbnailUrl}
                      alt={comic.title}
                      className="w-full h-full object-cover transition-transform group-hover:scale-105"
                    />
                    
                    <div className="absolute top-0 right-0 p-1.5 flex flex-col gap-1 z-20">
                      <span className="bg-slate-900/70 backdrop-blur-sm text-white text-[10px] font-bold px-1.5 py-0.5 rounded shadow-sm">
                        {comic.images.length}p
                      </span>
                    </div>

                    <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity z-10" />
                  </div>

                  <div className="mt-2.5">
                    <h3 className="text-sm font-bold text-slate-800 line-clamp-2 leading-tight group-hover:text-blue-600 transition-colors">
                      {comic.title}
                    </h3>
                    <p className="text-[11px] text-slate-500 mt-1 flex items-center gap-1 font-medium">
                      쟈몽 <span className="w-0.5 h-0.5 rounded-full bg-slate-300"></span> 만화
                    </p>
                  </div>
                  
                  {isAdmin && (
                    <div className="absolute top-2 left-2 flex gap-1 xl:opacity-0 group-hover:opacity-100 transition-opacity z-30">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditingComic(comic);
                        }}
                        className="p-1.5 rounded-md bg-white/90 text-blue-600 hover:bg-white shadow-sm"
                      >
                        <Edit2 className="w-3.5 h-3.5" />
                      </button>
                      <button
                        onClick={(e) => handleDelete(e, comic.id)}
                        className="p-1.5 rounded-md bg-white/90 text-red-500 hover:bg-white shadow-sm"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <div className="w-16 h-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
                <BookOpen className="w-8 h-8 text-muted-foreground" />
              </div>
              <h3 className="text-lg font-medium mb-2">아직 등록된 작품이 없습니다</h3>
              <p className="text-sm text-muted-foreground">
                {isAdmin ? '새 만화를 업로드해보세요!' : '곧 새로운 작품이 업로드될 예정입니다.'}
              </p>
            </div>
          )}
        </div>
      </main>

      {/* Modal */}
      {selectedComic && (
        <ComicModal
          comic={selectedComic}
          onClose={() => setSelectedComic(null)}
        />
      )}
    </div>
  );
}
